}"},{"rank":5,"score":35.3195,"file_path":"internal/ui/workspaces/commands.go","start_line":164,"end_line":218,"focus_line":164,"snippet_start_line":164,"snippet_end_line":218,"symbol_start_line":164,"symbol_end_line":218,"language":"Go","kind":"function","symbol_id":"local/devdesk:Go:internal/ui/workspaces/commands.go:function:scanOneRepoCmd","symbol_name":"scanOneRepoCmd","qualified_name":"scanOneRepoCmd","signature":"func scanOneRepoCmd(repoPath string, opts scan.ScanOptions, contextName string, sem chan struct{}) tea.Cmd","signals":["graph:calls","graph:incoming","graph:callers","complete-symbol"],"snippet":"func scanOneRepoCmd(repoPath string, opts scan.ScanOptions, contextName string, sem chan struct{}) tea.Cmd {
